"""Regenerate the compact PC-98 ANK table from the pinned Spleen 8x16 BDF."""

from pathlib import Path


root = Path(__file__).parent
glyphs = {}
code = None
rows = []
in_bitmap = False

for line in (root / "spleen-8x16.bdf").read_text(encoding="ascii").splitlines():
    if line.startswith("STARTCHAR "):
        code = None
        rows = []
        in_bitmap = False
    elif line.startswith("ENCODING "):
        code = int(line.split()[1])
    elif line == "BITMAP":
        in_bitmap = True
    elif line == "ENDCHAR":
        if code is not None and 32 <= code <= 126:
            if len(rows) != 16:
                raise ValueError(f"Expected 16 rows for U+{code:04X}")
            glyphs[code] = rows
        in_bitmap = False
    elif in_bitmap:
        rows.append(int(line, 16))

if set(glyphs) != set(range(32, 127)):
    raise ValueError("Spleen BDF does not cover printable ASCII")

lines = [
    "/* Generated by generate_ascii.py from Spleen 8x16, BSD-2-Clause.",
    " * Pinned source: fcambus/spleen@57f9219328c9f5873085320fe8bc8f7dd34b8791. */",
    "static const unsigned char spleen_ascii_8x16[95][16] = {",
]
for code in range(32, 127):
    values = ", ".join(f"0x{row:02x}" for row in glyphs[code])
    lines.append(f"    {{{values}}}, /* U+{code:04X} */")
lines.append("};")
(root / "spleen_ascii_8x16.h").write_text("\n".join(lines) + "\n", encoding="ascii")
